// Probe: does http.Client().close() while a POST is in flight abort it?
// Mirrors generate_image.dart's `cancellable(...)` + `finally client.close()`.
import 'dart:async';
import 'dart:io';

import 'package:http/http.dart' as http;

Future<void> main() async {
  final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
  server.listen((req) async {
    // Simulate a long paid generation: hold the response for 30s.
    await Future<void>.delayed(const Duration(seconds: 30));
    req.response.write('{"done":true}');
    await req.response.close();
  });
  final url = 'http://127.0.0.1:${server.port}/v1/images';

  final client = http.Client();
  final work = client.post(Uri.parse(url), body: 'prompt=a cat');
  unawaited(work.catchError((Object _) => http.Response('aborted', 599)));

  // Let the request go out, then cancel: close the client like the
  // `finally` block does while the POST is still awaiting its response.
  await Future<void>.delayed(const Duration(milliseconds: 200));
  final completedBeforeClose = await work.timeout(
    const Duration(milliseconds: 100),
    onTimeout: () => http.Response('still-in-flight', 598),
  );
  client.close(); // <-- generate_image's finally
  await Future<void>.delayed(const Duration(milliseconds: 300));
  // After the close: can the same client's in-flight work still complete?
  // We open a fresh client to ask whether the SERVER side saw an abort.
  // Instead, simplest observable: the original work future's outcome.
  final after = await work.timeout(
    const Duration(milliseconds: 500),
    onTimeout: () => http.Response('still-in-flight-after-close', 598),
  );
  // ignore: avoid_print
  print('before close: ${completedBeforeClose.statusCode}');
  // ignore: avoid_print
  print('after close:  ${after.statusCode}');
  await server.close(force: true);
}

