  await Future<void>.delayed(const Duration(seconds: 2500 ~/ 1000 + 1));
  // ignore: avoid_print
  print('server completed requests: $completed (1 = the paid POST finished)');
  await server.close(force: true);
  // Cancel while the POST is in flight:
  Timer(const Duration(milliseconds: 300), () => source.cancel('esc'));
}

